function validate(input) {
  const [{ Salary = [] }] = input;
  const ids = new Set();
  for (const [id, , sex] of Salary) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Salary.`;
    if (sex !== 'm' && sex !== 'f') return `Employee ${id} has sex ${sex}; it must be 'm' or 'f'.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const names = ['A', 'B', 'C', 'D', 'Ana', 'Bob', 'Kim', 'Ravi', 'Sofia', 'Lee'];
  // Ids are drawn from a shuffled range so they are unique but not in insertion order.
  const ids = Array.from({ length: small ? 20 : count }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  // A per-table bias makes all-'m' or all-'f' tables appear now and then.
  const bias = rand() < 0.2 ? 0 : rand() < 0.25 ? 1 : rand();
  const Salary = [];
  for (let i = 0; i < count; i++) Salary.push([ids[i], names[Math.floor(rand() * names.length)], rand() < bias ? 'm' : 'f', 100 * Math.floor(rand() * 100)]);
  return [{ Salary }];
}
